const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const empty={type:'object',properties:{},additionalProperties:false};const action={type:'object',properties:{observationId:{type:'string'}},additionalProperties:false};const defs=[['start_run','Start a real-time run; time continues while the agent thinks.',{type:'object',properties:{seed:{type:'integer',minimum:0,maximum:4294967295},mode:{type:'string',enum:['benchmark','practice']},maxJumps:{type:'integer',enum:[1,2]}},additionalProperties:false},api.start,false],['capture_frame','Capture current game pixels plus a timestamp ID; does not pause.',empty,api.captureFrame,true],['jump','Press jump once. Release then press for the second airborne jump in 2-jump mode. Landing resets the allowance. Optional observation ID measures observation-to-command age.',action,api.jump,false],['release_jump','Release the jump input. Does not shorten the fixed jump.',action,api.release,false],['get_run_result','Read current public score or the completed run record.',empty,api.result,true]];for(const [name,description,inputSchema,execute,readOnlyHint]of defs){try{Promise.resolve(context.registerTool({name,description,inputSchema,annotations:{readOnlyHint,untrustedContentHint:false},execute(input={}){if(typeof input!=='object'||input===null||Array.isArray(input))throw new Error('Expected object');for(const k of Object.keys(input))if(!(k in inputSchema.properties))throw new Error('Unknown argument');if(input.observationId!==undefined&&typeof input.observationId!=='string')throw new Error('Invalid observation ID');return execute(input);}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
